import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.Dp0m3YJZ.js";const b=JSON.parse('{"title":"09 · WUFS 檔案系統","description":"","frontmatter":{},"headers":[],"relativePath":"topics/filesystem.md","filePath":"topics/filesystem.md","lastUpdated":null}'),o={name:"topics/filesystem.md"};function d(i,e,r,l,p,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="_09-·-wufs-檔案系統" tabindex="-1">09 · WUFS 檔案系統 <a class="header-anchor" href="#_09-·-wufs-檔案系統" aria-label="Permalink to &quot;09 · WUFS 檔案系統&quot;">​</a></h1><p>磁碟只提供編號磁區，不知道 <code>/home/user/note.txt</code> 是什麼。WUFS 是 WUWAOS 自訂的檔案系統，將路徑轉成 inode，再找到存放內容的磁區。</p><h2 id="從名稱到硬體" tabindex="-1">從名稱到硬體 <a class="header-anchor" href="#從名稱到硬體" aria-label="Permalink to &quot;從名稱到硬體&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shell 的 cat／write／fan</span></span>
<span class="line"><span>  → 使用者 API → 檔案系統 syscall</span></span>
<span class="line"><span>  → fs.c：路徑與 inode → block.c：512-byte 磁區</span></span>
<span class="line"><span>  → VirtIO-MMIO → QEMU 的 build/wuwaos.img</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Linux 風格的 <code>/bin</code>、<code>/boot</code>、<code>/dev</code>、<code>/home/user</code> 是目錄命名慣例，並不表示 WUFS 可被 Linux 直接掛載，也不表示這些目錄已具備 Linux 的全部語意。</p><h2 id="磁碟資料結構" tabindex="-1">磁碟資料結構 <a class="header-anchor" href="#磁碟資料結構" aria-label="Permalink to &quot;磁碟資料結構&quot;">​</a></h2><table tabindex="0"><thead><tr><th>結構</th><th>負責什麼</th></tr></thead><tbody><tr><td>Superblock（檔案系統總表）</td><td>記錄格式標記與布局</td></tr><tr><td>Inode bitmap（索引節點位元圖）</td><td>哪些 inode 已配置</td></tr><tr><td>Block bitmap（資料區塊位元圖）</td><td>哪些磁區已配置</td></tr><tr><td>Inode table（索引節點表）</td><td>128 個 inode，每個 80 bytes</td></tr><tr><td>Directory entries（目錄項目）</td><td>將名稱對應到 inode</td></tr><tr><td>Data blocks（資料區塊）</td><td>一般檔案內容或目錄資料</td></tr></tbody></table><p>inode 有 8 個直接指標與 8 個單層間接指標。每個間接區塊可放 128 個 4-byte 指標，因此最大內容是 <code>(8 + 8 * 128) * 512 = 528384 bytes</code>，約 516 KiB；不是無上限大檔案。</p><h2 id="路徑查找與讀寫" tabindex="-1">路徑查找與讀寫 <a class="header-anchor" href="#路徑查找與讀寫" aria-label="Permalink to &quot;路徑查找與讀寫&quot;">​</a></h2><p><code>kernel/fs.c</code> 從根目錄開始，逐段查找名稱與 inode，最後依檔案內 offset（位移）找直接或間接區塊。建立檔案要配置 inode，擴展內容還要配置資料區塊與必要的間接區塊。</p><p>由於 inode 為 80 bytes、磁區為 512 bytes，有些 inode 會跨磁區。<code>inode_read</code>／<code>inode_write</code> 依每個磁區剩餘長度分段搬移；寫入先讀出原磁區再修改，保護旁邊 inode 的內容。</p><p>核心介面的宣告見 <a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/fs.h" target="_blank" rel="noreferrer">kernel/fs.h（GitHub）</a>：初始化、列目錄、建立目錄／檔案、讀取與整檔覆寫。</p><p>這是 path-based（直接以路徑呼叫）介面，還沒有完整 open／close／seek 與通用檔案描述號表。<code>fs_write</code> 是整檔覆寫，沒有 append（附加寫入）。</p><h2 id="在-qemu-操作" tabindex="-1">在 QEMU 操作 <a class="header-anchor" href="#在-qemu-操作" aria-label="Permalink to &quot;在 QEMU 操作&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls /</span></span>
<span class="line"><span>mkdir /home/user/notes</span></span>
<span class="line"><span>touch /home/user/notes/today.txt</span></span>
<span class="line"><span>write /home/user/notes/today.txt hello_WUWAOS</span></span>
<span class="line"><span>cat /home/user/notes/today.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>若目錄已存在，mkdir 可能回 -17；不用再建立一次。write 的文字參數目前只能是一個不含空白的 token（解析單位）；有空白或多行內容請用 fan。</p><p>cat 會在非空內容末端缺少換行時補一個「顯示用換行」，防止提示字元黏在文字後；不會因此修改檔案內容。退出並重新啟動 QEMU 後，再 cat 應仍可讀回。</p><h2 id="持久性與限制" tabindex="-1">持久性與限制 <a class="header-anchor" href="#持久性與限制" aria-label="Permalink to &quot;持久性與限制&quot;">​</a></h2><p><code>tools/make_disk.py</code> 在主機維護 16 MiB 原始磁碟映像，已有 WUFS 時保留使用者檔案並更新 <code>/boot/kernel.elf</code> 副本。不要用刪除映像檔的方式重新建置。</p><p>沒有刪除、重新命名、權限、連結、掛載其他格式、journal（日誌）或掉電交易保護；資料持久保存不等於每一次寫入都具備原子性。</p><p>觀念參考：<code>notes/Chapter 13 file system Interface.md</code>、<code>notes/chapter 14 File-System Implementation.md</code>、<code>notes/chapter 15 File System Internals.md</code>。WUFS 格式與既有持久性驗收見 <a href="./../SPEC-06-filesystem.html">Spec 06</a>。</p>`,21)])])}const m=a(o,[["render",d]]);export{b as __pageData,m as default};
